import java.util.Scanner;

public class Main {
    static int n_value, k_value, p_value;
    static int[][] cache;
    static int[] factorials, inv_factorials;

    static int fastExponentiation(int base, int exponent) {
        long result = 1;
        long current_power = base;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * current_power) % p_value;
            }
            current_power = (current_power * current_power) % p_value;
            exponent >>= 1;
        }
        return (int) result;
    }

    static int extractLowbit(int x) {
        return x & (-x);
    }

    static void prepare() {
        factorials = new int[n_value + 1];
        inv_factorials = new int[n_value + 1];
        factorials[0] = 1;
        for (int i = 1; i <= n_value; i++) {
            factorials[i] = (int) ((long) factorials[i - 1] * i % p_value);
        }
        inv_factorials[n_value] = fastExponentiation(factorials[n_value], p_value - 2);
        for (int i = n_value; i >= 1; i--) {
            inv_factorials[i - 1] = (int) ((long) inv_factorials[i] * i % p_value);
        }
    }

    static int recursiveCompute(int current, int S) {
        if (cache[current][S] != -1) return cache[current][S];
        if (S == 0) {
            long val = factorials[n_value];
            for (int i = 1; i <= current; i++) {
                val = (val * (k_value - i + 1)) % p_value;
            }
            cache[current][S] = (int) val;
            return cache[current][S];
        }
        long sum = 0;
        int U = S - extractLowbit(S);
        for (int T = U; T != 0; T = (T - 1) & U) {
            sum = (sum + (long) inv_factorials[S - T] * recursiveCompute(current + 1, T)) % p_value;
        }
        sum = (sum + (long) inv_factorials[S] * recursiveCompute(current + 1, 0)) % p_value;
        cache[current][S] = (int) sum;
        return cache[current][S];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n_value = sc.nextInt();
        k_value = sc.nextInt();
        p_value = sc.nextInt();

        int ans = 1;
        for (int i = 1; i <= n_value; i++) {
            ans = (int) ((long) ans * k_value % p_value);
        }

        if (n_value % 2 == 0) {
            prepare();
            cache = new int[n_value + 1][n_value + 1];
            for (int i = 0; i <= n_value; i++) {
                for (int j = 0; j <= n_value; j++) {
                    cache[i][j] = -1;
                }
            }
            ans = (ans - recursiveCompute(0, n_value) + p_value) % p_value;
        }

        System.out.println(ans);
        sc.close();
    }
}
